#!/usr/bin/env bash
# GRAFANA_MODE=api: adds the stack's datasources and every app's dashboards to an EXISTING Grafana
# over its HTTP API. Generated by render.sh. Safe to re-run (creates or updates by uid).
#   GRAFANA_URL=https://grafana.example.com GRAFANA_TOKEN=<service-account token> ./import.sh
# The service account needs the Admin role (datasources) - or Editor if the datasources already exist
# and you run with SKIP_DATASOURCES=1.
# Needs bash and curl. Datasource urls (how Grafana reaches the stack):
#   Prometheus @@PROMETHEUS_URL_FOR_GRAFANA@@
#   Tempo      @@TEMPO_URL_FOR_GRAFANA@@
set -euo pipefail
cd "$(dirname "$0")"
: "${GRAFANA_URL:?set GRAFANA_URL (e.g. https://grafana.example.com)}"
: "${GRAFANA_TOKEN:?set GRAFANA_TOKEN (service-account token)}"
GRAFANA_URL=${GRAFANA_URL%/}

api() {   # method path [json-file]  -> prints body, returns 0 on 2xx
  local method=$1 path=$2 data=${3:-} out code
  out=$(mktemp)
  code=$(curl -sS -o "$out" -w '%{http_code}' -X "$method" \
    -H "Authorization: Bearer $GRAFANA_TOKEN" -H 'Content-Type: application/json' \
    ${data:+--data-binary "@$data"} ${GRAFANA_INSECURE:+-k} "$GRAFANA_URL$path")
  cat "$out"; rm -f "$out"
  [ "${code:0:1}" = 2 ]
}

echo "Grafana: $GRAFANA_URL"
api GET /api/health >/dev/null || { echo "Grafana not reachable" >&2; exit 1; }

if [ -z "${SKIP_DATASOURCES:-}" ]; then
  for ds in datasources/*.json; do
    uid=$(basename "$ds" .json)
    if api GET "/api/datasources/uid/$uid" >/dev/null 2>&1; then
      api PUT "/api/datasources/uid/$uid" "$ds" >/dev/null && echo "  datasource $uid updated"
    else
      api POST /api/datasources "$ds" >/dev/null && echo "  datasource $uid created"
    fi
  done
fi

for app_dir in dashboards/*/; do
  folder_json="$app_dir/folder.json"
  folder_uid=$(sed -n 's/.*"uid": *"\([^"]*\)".*/\1/p' "$folder_json")
  if ! api GET "/api/folders/$folder_uid" >/dev/null 2>&1; then
    api POST /api/folders "$folder_json" >/dev/null
  fi
  echo "  folder $folder_uid"
  for d in "$app_dir"*.json; do
    [ "$(basename "$d")" = folder.json ] && continue
    payload=$(mktemp)
    { printf '{"folderUid":"%s","overwrite":true,"message":"observability-kit import.sh","dashboard":' "$folder_uid"
      cat "$d"; printf '}'; } > "$payload"
    if api POST /api/dashboards/db "$payload" >/dev/null; then echo "    $(basename "$d")"; else echo "    $(basename "$d") FAILED" >&2; fi
    rm -f "$payload"
  done
done
echo "Done."
